export default {"html":"<p data-line=\"0\" class=\"code-line\">Suppose you create a very simple component in Stencil: a button component with a <code>label</code> attribute.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"2\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  tag: </span><span style=\"color:#9ECBFF\">'my-button'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  styleUrl: </span><span style=\"color:#9ECBFF\">'./my-button.scss'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  scoped: </span><span style=\"color:#79B8FF\">true</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> ButtonComponent</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  @</span><span style=\"color:#B392F0\">Prop</span><span style=\"color:#E1E4E8\">() </span><span style=\"color:#FFAB70\">label</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#F97583\"> =</span><span style=\"color:#9ECBFF\"> ''</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  render</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#E1E4E8\"> (</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      &lt;</span><span style=\"color:#85E89D\">button</span><span style=\"color:#E1E4E8\">&gt;{</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.label}&lt;/</span><span style=\"color:#85E89D\">button</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    );</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"19\" class=\"code-line\">You can use it as <code>&lt;my-button label=\"button\"&gt;&lt;/my-button&gt;</code>. On the initial render, <code>render()</code> runs with the <code>@Prop</code> in place, so the result is naturally displayed as <code>&lt;button&gt;button&lt;/button&gt;</code>.</p>\n<p data-line=\"21\" class=\"code-line\">What happens if you change the <code>label</code> attribute in JavaScript after rendering?</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"23\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> button</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> document.</span><span style=\"color:#B392F0\">querySelector</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'my-button'</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">button.</span><span style=\"color:#B392F0\">setAttribute</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'label'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#9ECBFF\">'my-button'</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"28\" class=\"code-line\">Even after this change, <code>my-button</code> is not re-rendered. From the perspective of <code>ButtonComponent</code>, only the value of <code>this.label</code> changed, so <code>render()</code> does not run again. Stencil works this way to avoid the cost of watching every <code>@Prop</code> at the value level and to prevent unnecessary re-renders.</p>\n<p data-line=\"30\" class=\"code-line\">First, Stencil provides the <code>@Watch</code> decorator to detect changes. Let us update the component above.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"33\"><span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\"> @</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">   tag: </span><span style=\"color:#9ECBFF\">'my-button'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">   styleUrl: </span><span style=\"color:#9ECBFF\">'./my-button.scss'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">   scoped: </span><span style=\"color:#79B8FF\">true</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\"> })</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#F97583\"> export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> ButtonComponent</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">   @</span><span style=\"color:#B392F0\">Prop</span><span style=\"color:#E1E4E8\">() </span><span style=\"color:#FFAB70\">label</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#F97583\"> =</span><span style=\"color:#9ECBFF\"> ''</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">   @</span><span style=\"color:#B392F0\">Watch</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'label'</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#F97583\">   async</span><span style=\"color:#B392F0\"> watchLabelHandler</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">   }</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\"> </span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#B392F0\">   render</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#F97583\">     return</span><span style=\"color:#E1E4E8\"> (</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">       &lt;</span><span style=\"color:#85E89D\">button</span><span style=\"color:#E1E4E8\">&gt;{</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.label}&lt;/</span><span style=\"color:#85E89D\">button</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">     );</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">   }</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\"> }</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"53\" class=\"code-line\">Now, whenever <code>label</code> changes, <code>watchLabelHandler()</code> runs. However, <code>render()</code> still does not run. For <code>render()</code> to run, a property decorated with <code>@State</code> must change, so let us add a <code>@State _label</code> property for re-render tracking.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"55\"><span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\"> @</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">   tag: </span><span style=\"color:#9ECBFF\">'my-button'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">   styleUrl: </span><span style=\"color:#9ECBFF\">'./my-button.scss'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">   scoped: </span><span style=\"color:#79B8FF\">true</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\"> })</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#F97583\"> export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> ButtonComponent</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">   @</span><span style=\"color:#B392F0\">Prop</span><span style=\"color:#E1E4E8\">() </span><span style=\"color:#FFAB70\">label</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#F97583\"> =</span><span style=\"color:#9ECBFF\"> ''</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#E1E4E8\">   @</span><span style=\"color:#B392F0\">State</span><span style=\"color:#E1E4E8\">() </span><span style=\"color:#FFAB70\">_label</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#E1E4E8\">;   </span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">   @</span><span style=\"color:#B392F0\">Watch</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'label'</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#F97583\">   async</span><span style=\"color:#B392F0\"> watchLabelHandler</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#F97583\"></span><span style=\"color:#79B8FF\">     this</span><span style=\"color:#E1E4E8\">._label </span><span style=\"color:#F97583\">=</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.label;</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">   }</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\"> </span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#B392F0\">   render</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#F97583\">     return</span><span style=\"color:#E1E4E8\"> (</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">       &lt;</span><span style=\"color:#85E89D\">button</span><span style=\"color:#E1E4E8\">&gt;{</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.label}&lt;/</span><span style=\"color:#85E89D\">button</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">     );</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">   }</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\"> }</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"77\" class=\"code-line\">Now, whenever the <code>label</code> attribute changes, <code>@Watch('label')</code> runs <code>watchLabelHandler()</code>, and updating <code>_label</code> inside it triggers a re-render.</p>\n<p data-line=\"79\" class=\"code-line\">Simple, right?</p>\n<p data-line=\"81\" class=\"code-line\">See you next time.</p>\n","headings":[]} as const;
